package main

import (
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"testing"
)

func TestFetchModelDownloadsToDestination(t *testing.T) {
	payload := []byte("fake-gguf-bytes")
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Length", "15")
		_, _ = w.Write(payload)
	}))
	defer srv.Close()

	dest := filepath.Join(t.TempDir(), "models", "sub", "model.gguf")
	if err := fetchModel(srv.URL, dest, io.Discard); err != nil {
		t.Fatalf("fetchModel: %v", err)
	}
	got, err := os.ReadFile(dest)
	if err != nil {
		t.Fatalf("read dest: %v", err)
	}
	if string(got) != string(payload) {
		t.Fatalf("dest content = %q, want %q", got, payload)
	}
}

func TestFetchModelSkipsWhenPresent(t *testing.T) {
	hits := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hits++
		_, _ = w.Write([]byte("data"))
	}))
	defer srv.Close()

	dest := filepath.Join(t.TempDir(), "model.gguf")
	if err := os.WriteFile(dest, []byte("data"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := fetchModel(srv.URL, dest, io.Discard); err != nil {
		t.Fatalf("fetchModel: %v", err)
	}
	if hits != 0 {
		t.Fatalf("server was hit %d times; expected skip when file present", hits)
	}
}

package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"

	"github.com/jimmykarily/voice-keyboard/pkg/websettings"
)

// defaultModelURL is the curated GGUF for the default nemotron streaming model.
// Keep the filename in sync with config.Default().Engine.ModelPath and the
// Makefile MODEL_URL.
const defaultModelURL = "https://huggingface.co/mudler/parakeet-cpp-gguf/resolve/main/nemotron-3.5-asr-streaming-0.6b-f16.gguf?download=true"

// fetchModel downloads url to dest (creating parent dirs), printing progress to
// out. It reuses websettings.Downloader, which skips the download if dest
// already exists. It returns when the download is done or errors.
func fetchModel(url, dest string, out io.Writer) error {
	if err := os.MkdirAll(filepath.Dir(dest), 0o755); err != nil {
		return fmt.Errorf("create model dir: %w", err)
	}
	d := websettings.NewDownloader(nil)
	s := d.Start(url, dest)
	for s.State == "running" {
		if s.Total > 0 {
			fmt.Fprintf(out, "\rdownloading %s: %d/%d bytes", s.Filename, s.Done, s.Total)
		} else {
			fmt.Fprintf(out, "\rdownloading %s: %d bytes", s.Filename, s.Done)
		}
		time.Sleep(100 * time.Millisecond)
		s = d.Status()
	}
	if s.State == "error" {
		return fmt.Errorf("download failed: %s", s.Err)
	}
	fmt.Fprintf(out, "\rmodel ready at %s\n", dest)
	return nil
}

package stt

import "testing"

func TestStripSpecialTokens(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want string
	}{
		{"no tokens untouched", "hello world", "hello world"},
		{"trailing language tag", "picked up. <en-US>", "picked up. "},
		{"bare language tag", "hello <en> there", "hello there"},
		{"leading tag", "<de-DE>guten tag", "guten tag"},
		{"square bracket token", "text [PAD] more", "text more"},
		{"multiple tags collapse spaces", "a <en-US> <en-US> b", "a b"},
		{"empty string", "", ""},
		{"preserves single trailing space", "word ", "word "},
		{"leaves real angle-bracket prose", "less < than and > greater", "less < than and > greater"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := stripSpecialTokens(tc.in); got != tc.want {
				t.Errorf("stripSpecialTokens(%q) = %q, want %q", tc.in, got, tc.want)
			}
		})
	}
}

package websettings

import (
