func TestCatalogHasStreamingNemotron(t *testing.T) {
	var found *Model
	for i := range Catalog() {
		if Catalog()[i].Filename == "nemotron-3.5-asr-streaming-0.6b-f16.gguf" {
			found = &Catalog()[i]
			break
		}
	}
	if found == nil {
		t.Fatal("catalog missing nemotron-3.5-asr-streaming-0.6b-f16.gguf")
	}
	if !found.Streaming || !found.Multilingual {
		t.Errorf("nemotron f16 should be Streaming and Multilingual, got %+v", *found)
	}
}

func TestDownloadURL(t *testing.T) {
	got := DownloadURL("nemotron-3.5-asr-streaming-0.6b-f16.gguf")
	want := "https://huggingface.co/mudler/parakeet-cpp-gguf/resolve/main/nemotron-3.5-asr-streaming-0.6b-f16.gguf?download=true"
	if got != want {
		t.Errorf("DownloadURL = %q, want %q", got, want)
	}
}

func TestInstalledIn(t *testing.T) {
	dir := t.TempDir()
	m := Model{Filename: "x.gguf"}
	if m.InstalledIn(dir) {
		t.Error("InstalledIn true before file exists")
	}
	if err := os.WriteFile(filepath.Join(dir, "x.gguf"), []byte("data"), 0o644); err != nil {
		t.Fatal(err)
	}
	if !m.InstalledIn(dir) {
		t.Error("InstalledIn false after file created")
	}
}

func TestCatalogURLsWellFormed(t *testing.T) {
	for _, m := range Catalog() {
		if !strings.HasSuffix(m.Filename, ".gguf") {
			t.Errorf("model %q filename %q not a .gguf", m.ID, m.Filename)
		}
		if m.URL != DownloadURL(m.Filename) {
			t.Errorf("model %q URL %q != DownloadURL(%q)", m.ID, m.URL, m.Filename)
		}
	}
}

package audio

import (
	"reflect"
	"testing"
)

func TestChunkerEmitsFullChunks(t *testing.T) {
	c := newChunker(2)
	if got := c.push([]float32{1}); got != nil {
		t.Fatalf("push(1) = %v, want nil (not yet a full chunk)", got)
	}
	got := c.push([]float32{2, 3, 4, 5})
	want := [][]float32{{1, 2}, {3, 4}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("push = %v, want %v", got, want)
	}
	if rem := c.flush(); !reflect.DeepEqual(rem, []float32{5}) {
		t.Fatalf("flush = %v, want [5]", rem)
	}
	if rem := c.flush(); rem != nil {
		t.Fatalf("second flush = %v, want nil", rem)
	}
}

