func TestMenuSettingsClickOpensURL(t *testing.T) {
	settingsCh := make(chan struct{}, 1)
	quitCh := make(chan struct{})
	opened := make(chan string, 1)
	go handleMenu(context.Background(), settingsCh, quitCh, "http://x/?t=1",
		func(url string) error { opened <- url; return nil }, func() {})
	settingsCh <- struct{}{}
	select {
	case got := <-opened:
		if got != "http://x/?t=1" {
			t.Fatalf("opened %q, want the given URL", got)
		}
	case <-time.After(time.Second):
		t.Fatal("opener was not called")
	}
}

