	quitCh := make(chan struct{}, 1)
	called := make(chan struct{})
	go handleMenu(context.Background(), settingsCh, quitCh, "http://x",
		func(string) error { return nil }, func() { close(called) })
	quitCh <- struct{}{}
	select {
	case <-called:
	case <-time.After(time.Second):
		t.Fatal("quit func was not called")
	}
}

