package stt_test

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"unicode"

	"github.com/go-audio/wav"

	"github.com/jimmykarily/voice-keyboard/pkg/stt"
)

// modelPath resolves the GGUF model, skipping the test if it is absent so the
// suite stays green on machines that have not run `make model`.
func modelPath(t *testing.T) string {
	t.Helper()
	p := os.Getenv("VOICEKBD_MODEL")
	if p == "" {
		home, err := os.UserHomeDir()
		if err != nil {
			t.Fatalf("home dir: %v", err)
		}
		p = filepath.Join(home, ".local", "share", "voicekbd", "models", "tdt-0.6b-v3-f16.gguf")
	}
	if _, err := os.Stat(p); err != nil {
		t.Skipf("model not found at %s (run `make model`): %v", p, err)
	}
	return p
}

// loadWAV decodes a 16-bit PCM mono WAV into normalized float32 samples.
func loadWAV(t *testing.T, path string) ([]float32, int) {
	t.Helper()
	f, err := os.Open(path)
	if err != nil {
		t.Fatalf("open fixture: %v", err)
	}
	defer f.Close()

	dec := wav.NewDecoder(f)
	buf, err := dec.FullPCMBuffer()
	if err != nil {
		t.Fatalf("decode wav: %v", err)
	}
	if buf.Format.NumChannels != 1 {
		t.Fatalf("fixture must be mono, got %d channels", buf.Format.NumChannels)
	}

	scale := float32(int(1) << (uint(buf.SourceBitDepth) - 1)) // 32768 for 16-bit
	out := make([]float32, len(buf.Data))
	for i, s := range buf.Data {
		out[i] = float32(s) / scale
	}
	return out, buf.Format.SampleRate
}

func TestPnCSmoke(t *testing.T) {
	eng, err := stt.New(modelPath(t))
	if err != nil {
		t.Fatalf("load model: %v", err)
	}
	defer eng.Close()

	pcm, sr := loadWAV(t, filepath.Join("testdata", "smoke.wav"))

	text, err := eng.Transcribe(pcm, sr)
	if err != nil {
		t.Fatalf("transcribe: %v", err)
	}
	t.Logf("transcript: %q", text)

	if strings.TrimSpace(text) == "" {
		t.Fatal("empty transcript: the STT path produced no text")
	}
	if !strings.ContainsFunc(text, unicode.IsUpper) {
		t.Error("no uppercase letter: capitalization (PnC) may be lost on the GGUF path")
	}
	if !strings.ContainsAny(text, ".,?!") {
		t.Error("no punctuation: PnC may be lost on the GGUF path")
	}
}

package websettings

import (
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"testing"
	"time"
)

func waitState(t *testing.T, d *Downloader, want string) DownloadStatus {
	t.Helper()
	deadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		s := d.Status()
		if s.State == want {
			return s
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatalf("state never became %q (last %q)", want, d.Status().State)
	return DownloadStatus{}
}

func TestDownloadSuccess(t *testing.T) {
	body := make([]byte, 4096)
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Length", "4096")
		_, _ = w.Write(body)
	}))
	defer srv.Close()

	dir := t.TempDir()
	dest := filepath.Join(dir, "model.gguf")
	d := NewDownloader(srv.Client())
	d.Start(srv.URL, dest)

	s := waitState(t, d, "done")
	if s.Done != 4096 || s.Total != 4096 {
		t.Errorf("done/total = %d/%d, want 4096/4096", s.Done, s.Total)
	}
	if _, err := os.Stat(dest); err != nil {
		t.Errorf("dest not written: %v", err)
	}
	if _, err := os.Stat(dest + ".part"); !os.IsNotExist(err) {
		t.Error(".part file should be gone after success")
	}
}

func TestDownloadSkipsWhenPresent(t *testing.T) {
	dir := t.TempDir()
	dest := filepath.Join(dir, "model.gguf")
	if err := os.WriteFile(dest, []byte("already here"), 0o644); err != nil {
		t.Fatal(err)
	}
	d := NewDownloader(http.DefaultClient)
	s := d.Start("http://unused.invalid/x", dest)
	if s.State != "done" {
		t.Errorf("state = %q, want done (present file should skip)", s.State)
	}
}

func TestDownloadErrorOnBadStatus(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Error(w, "nope", http.StatusNotFound)
	}))
	defer srv.Close()

	dir := t.TempDir()
	dest := filepath.Join(dir, "model.gguf")
	d := NewDownloader(srv.Client())
	d.Start(srv.URL, dest)

	s := waitState(t, d, "error")
	if s.Err == "" {
		t.Error("error state should carry a message")
	}
	if _, err := os.Stat(dest + ".part"); !os.IsNotExist(err) {
		t.Error(".part file should be removed on error")
	}
}

package main

import (
	"fmt"
	"testing"

	"github.com/jimmykarily/voice-keyboard/pkg/ipc"
)

func TestClassifyArgs(t *testing.T) {
	cases := []struct {
		name      string
		args      []string
		wantVerb  ipc.Command
		wantIsCtl bool
		wantErr   bool
	}{
		{"none is daemon", nil, "", false, false},
		{"empty is daemon", []string{}, "", false, false},
		{"toggle", []string{"toggle"}, ipc.CmdToggle, true, false},
		{"start", []string{"start"}, ipc.CmdStart, true, false},
		{"stop", []string{"stop"}, ipc.CmdStop, true, false},
		{"status", []string{"status"}, ipc.CmdStatus, true, false},
		{"subscribe", []string{"subscribe"}, ipc.CmdSubscribe, true, false},
		{"quit", []string{"quit"}, ipc.CmdQuit, true, false},
		{"settings-url is not public", []string{"settings-url"}, "", false, true},
		{"unknown verb errors", []string{"bogus"}, "", false, true},
		{"verb with extra arg errors", []string{"toggle", "x"}, "", false, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			verb, isCtl, err := classifyArgs(tc.args)
			if (err != nil) != tc.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tc.wantErr)
			}
			if err != nil {
				return
			}
			if verb != tc.wantVerb {
				t.Errorf("verb = %q, want %q", verb, tc.wantVerb)
			}
			if isCtl != tc.wantIsCtl {
				t.Errorf("isControl = %v, want %v", isCtl, tc.wantIsCtl)
			}
		})
	}
}

func TestRunControlSendsCommandAndPrintsReply(t *testing.T) {
	oldSend := sendCmd
	defer func() { sendCmd = oldSend }()
	var gotSocket string
	var gotCmd ipc.Command
	sendCmd = func(socket string, cmd ipc.Command) (string, error) {
		gotSocket = socket
		gotCmd = cmd
		return "idle", nil
	}
	if err := runControl("/tmp/x.sock", ipc.CmdStatus); err != nil {
		t.Fatalf("runControl error: %v", err)
	}
	if gotSocket != "/tmp/x.sock" {
		t.Errorf("socket = %q, want /tmp/x.sock", gotSocket)
	}
	if gotCmd != ipc.CmdStatus {
		t.Errorf("cmd = %q, want status", gotCmd)
	}
}

func TestRunControlPropagatesSendError(t *testing.T) {
	oldSend := sendCmd
	defer func() { sendCmd = oldSend }()
	sendCmd = func(string, ipc.Command) (string, error) {
		return "", fmt.Errorf("cannot reach daemon")
	}
	if err := runControl("/tmp/x.sock", ipc.CmdStatus); err == nil {
		t.Fatal("expected runControl to propagate the send error")
	}
}

package audio

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/go-audio/wav"
)

func loadFixtureWAV(t *testing.T, path string) ([]float32, int) {
	t.Helper()
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	dec := wav.NewDecoder(f)
	buf, err := dec.FullPCMBuffer()
	if err != nil {
		t.Fatal(err)
	}
	if buf.Format.NumChannels != 1 {
		t.Fatalf("fixture must be mono, got %d channels", buf.Format.NumChannels)
	}
	scale := float32(int(1) << (uint(buf.SourceBitDepth) - 1))
	out := make([]float32, len(buf.Data))
	for i, s := range buf.Data {
		out[i] = float32(s) / scale
	}
	return out, buf.Format.SampleRate
}

// endpointFrame feeds fixed-size frames from pcm[startFrame:] through a fresh
// endpointer built from cfg's production parameters, returning the absolute
// frame index where it endpoints, or -1 if it never does.
func endpointFrame(cfg Config, pcm []float32, startFrame int) int {
	fs := cfg.frameSamples()
	ep := NewEndpointer(cfg.vadConfig())
	n := len(pcm) / fs
	for fi := startFrame; fi < n; fi++ {
		if ep.Push(pcm[fi*fs:fi*fs+fs]) == Endpoint {
			return fi
		}
	}
	return -1
}

func TestEndpointerShortFirstUtterance(t *testing.T) {
	// Regression: a short first word (~0.28s, ~11 above-threshold frames) must
	// still endpoint in the gap right after it, not be discarded as a blip such
	// that only a later longer utterance trips the endpoint.
	// Fixture layout: 0.5s ambient | 0.28s short word | gap1 0.78..1.98s |
	// 1.93s long word | gap2 3.91..5.11s.
	pcm, sr := loadFixtureWAV(t, filepath.Join("testdata", "short_utterance.wav"))
	cfg := DefaultConfig()
	if sr != cfg.SampleRate {
		t.Fatalf("fixture sample rate %d, want %d", sr, cfg.SampleRate)
	}
	frameSec := float64(cfg.FrameMillis) / 1000.0

	const shortWordEnd = 0.78
	const longWordStart = 1.98

	f := endpointFrame(cfg, pcm, 0)
	if f < 0 {
		t.Fatal("short first utterance: never endpointed")
	}
	tEnd := float64(f) * frameSec
	if tEnd <= shortWordEnd || tEnd >= longWordStart {
		t.Errorf("endpoint at %.2fs, want in gap 1 after the short word (~%.2f..%.2f); a later endpoint means the short word was wrongly discarded",
			tEnd, shortWordEnd, longWordStart)
	}
}

func TestEndpointerSilenceGapFixture(t *testing.T) {
	pcm, sr := loadFixtureWAV(t, filepath.Join("testdata", "silence_gap.wav"))
	cfg := DefaultConfig()
	if sr != cfg.SampleRate {
		t.Fatalf("fixture sample rate %d, want %d", sr, cfg.SampleRate)
	}
	frameSec := float64(cfg.FrameMillis) / 1000.0
	// Fixture layout (silence_gap.wav, generated via piper TTS + ffmpeg):
	//   0.00..0.50s  leading silence (ambient)
	//   0.50..2.83s  speech 1 ("Testing. One, two, three.")
	//   2.83..4.03s  silence gap (~1.2s, the only run longer than SilenceFrames)
	//   4.03..end    speech 2 ("Four, five, six, seven.")
	// A correct single-shot endpoint must fire inside the gap, before speech 2.
	const speech1End = 2.83
	const speech2Start = 4.03

	// Case 1: realistic use (leading ambient silence). Must endpoint in the gap.
	f1 := endpointFrame(cfg, pcm, 0)
	if f1 < 0 {
		t.Fatal("leading-ambient: never endpointed")
	}
	t1 := float64(f1) * frameSec
	if t1 <= speech1End-0.6 || t1 >= speech2Start {
		t.Errorf("leading-ambient: endpoint at %.2fs, want within the gap (~%.2f..%.2f)", t1, speech1End, speech2Start)
	}

	// Case 2: speak-immediately (feed from the speech onset, no leading ambient).
	// This is the regression the clamp fixes: calibrating on speech must not push
	// the threshold so high that speech is never detected. Must still endpoint
	// before speech2 begins.
	leadFrames := int(0.5 / frameSec)
	f2 := endpointFrame(cfg, pcm, leadFrames)
	if f2 < 0 {
		t.Fatal("speak-immediately: never endpointed (threshold calibrated on speech and not clamped)")
	}
	t2 := float64(f2) * frameSec
	if t2 <= speech1End-0.6 || t2 >= speech2Start {
		t.Errorf("speak-immediately: endpoint at %.2fs, want within the gap (~%.2f..%.2f)", t2, speech1End, speech2Start)
	}
}

