package stt_test

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/jimmykarily/voice-keyboard/pkg/stt"
)

// streamModelPath returns the streaming model path, or skips if it is absent.
// The streaming test needs a cache-aware streaming model (nemotron); the batch
// tdt model cannot open a stream.
func streamModelPath(t *testing.T) string {
	t.Helper()
	home, _ := os.UserHomeDir()
	p := filepath.Join(home, ".local", "share", "localai", "models", "parakeet-cpp", "nemotron-3.5-asr-streaming-0.6b-f16.gguf")
	if _, err := os.Stat(p); err != nil {
		t.Skipf("streaming model not present at %s (run 'make model'): %v", p, err)
	}
	return p
}

func TestStreamMatchesBatch(t *testing.T) {
	modelPath := streamModelPath(t)
	pcm, sr := loadWAV(t, filepath.Join("testdata", "smoke.wav"))

	eng, err := stt.New(modelPath)
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	defer eng.Close()

	batch, err := eng.Transcribe(pcm, sr)
	if err != nil {
		t.Fatalf("batch transcribe: %v", err)
	}

	se, ok := eng.(stt.StreamEngine)
	if !ok {
		t.Fatal("engine does not implement StreamEngine")
	}
	st, err := se.BeginStream("auto")
	if err != nil {
		t.Fatalf("begin stream: %v", err)
	}
	defer st.Close()

	const chunk = 1600 // 100 ms at 16 kHz
	var sb strings.Builder
	start := time.Now()
	for i := 0; i < len(pcm); i += chunk {
		end := i + chunk
		if end > len(pcm) {
			end = len(pcm)
		}
		delta, err := st.Feed(pcm[i:end])
		if err != nil {
			t.Fatalf("feed: %v", err)
		}
		sb.WriteString(delta)
	}
	tail, err := st.Finalize()
	if err != nil {
		t.Fatalf("finalize: %v", err)
	}
	sb.WriteString(tail)
	elapsed := time.Since(start)

	got := strings.TrimSpace(strings.Join(strings.Fields(sb.String()), " "))
	want := strings.TrimSpace(strings.Join(strings.Fields(batch), " "))
	if got != want {
		t.Errorf("streamed transcript mismatch:\n got  %q\n want %q", got, want)
	}

	// Realtime check: total feed+finalize time must be under the audio duration,
	// or streamed text will lag the speaker. This is the throughput gate.
	audioDur := time.Duration(float64(len(pcm)) / float64(sr) * float64(time.Second))
	t.Logf("stream compute %v for %v of audio (%.2fx realtime)", elapsed, audioDur, float64(audioDur)/float64(elapsed))
	if elapsed > audioDur {
		t.Logf("WARNING: streaming slower than realtime; consider a smaller quant (q8_0/q5_k) or the 120m model")
	}
}

func TestBeginStreamOnNonStreamingModelErrors(t *testing.T) {
	home, _ := os.UserHomeDir()
	batchModel := filepath.Join(home, ".local", "share", "voicekbd", "models", "tdt-0.6b-v3-f16.gguf")
	if _, err := os.Stat(batchModel); err != nil {
		t.Skipf("batch model not present: %v", err)
	}
	eng, err := stt.New(batchModel)
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	defer eng.Close()
	se := eng.(stt.StreamEngine)
	if _, err := se.BeginStream("auto"); err == nil {
		t.Fatal("expected BeginStream to fail on a non-streaming model")
	}
}

