package audio

import (
	"math"
	"testing"
)

// constFrame returns a frame whose every sample equals amp, so its RMS == amp.
func constFrame(n int, amp float32) []float32 {
	f := make([]float32, n)
	for i := range f {
		f[i] = amp
	}
	return f
}

func silenceFrame(n int) []float32 { return make([]float32, n) }

func TestFrameRMS(t *testing.T) {
	if got := frameRMS(constFrame(100, 0.5)); math.Abs(float64(got-0.5)) > 1e-6 {
		t.Fatalf("rms of constant 0.5 = %v, want 0.5", got)
	}
	if got := frameRMS(silenceFrame(100)); got != 0 {
		t.Fatalf("rms of silence = %v, want 0", got)
	}
}

func TestEndpointerDetectsUtterance(t *testing.T) {
	cfg := VADConfig{FrameSamples: 320, SilenceFrames: 3, MinSpeechFrames: 2, MaxFrames: 1000, CalibrationFrames: 2, ThresholdMultiplier: 3}
	ep := NewEndpointer(cfg)

	// Calibration: two low-noise frames establish the ambient floor.
	mustContinue(t, ep.Push(constFrame(320, 0.001)))
	mustContinue(t, ep.Push(constFrame(320, 0.001)))
	// Speech: four loud frames.
	for i := 0; i < 4; i++ {
		mustContinue(t, ep.Push(constFrame(320, 0.3)))
	}
	// Trailing silence: endpoint on the 3rd silence frame.
	mustContinue(t, ep.Push(silenceFrame(320)))
	mustContinue(t, ep.Push(silenceFrame(320)))
	if got := ep.Push(silenceFrame(320)); got != Endpoint {
		t.Fatalf("want Endpoint after trailing silence, got %v", got)
	}
}

func TestEndpointerRejectsShortBlip(t *testing.T) {
	cfg := VADConfig{FrameSamples: 320, SilenceFrames: 2, MinSpeechFrames: 5, MaxFrames: 1000, CalibrationFrames: 1, ThresholdMultiplier: 3}
	ep := NewEndpointer(cfg)
	ep.Push(constFrame(320, 0.001)) // calibrate

	// A 2-frame blip (< MinSpeechFrames=5) followed by silence must NOT endpoint.
	ep.Push(constFrame(320, 0.3))
	ep.Push(constFrame(320, 0.3))
	mustContinue(t, ep.Push(silenceFrame(320)))
	mustContinue(t, ep.Push(silenceFrame(320)))

	// A real utterance afterwards DOES endpoint.
	for i := 0; i < 5; i++ {
		mustContinue(t, ep.Push(constFrame(320, 0.3)))
	}
	mustContinue(t, ep.Push(silenceFrame(320)))
	if got := ep.Push(silenceFrame(320)); got != Endpoint {
		t.Fatalf("want Endpoint after a real utterance, got %v", got)
	}
}

func TestEndpointerMaxUtteranceFlush(t *testing.T) {
	cfg := VADConfig{FrameSamples: 320, SilenceFrames: 100, MinSpeechFrames: 1, MaxFrames: 5, CalibrationFrames: 1, ThresholdMultiplier: 3}
	ep := NewEndpointer(cfg)
	ep.Push(constFrame(320, 0.001))                            // frame 1 (calibration)
	mustContinue(t, ep.Push(constFrame(320, 0.3)))             // 2
	mustContinue(t, ep.Push(constFrame(320, 0.3)))             // 3
	mustContinue(t, ep.Push(constFrame(320, 0.3)))             // 4
	if got := ep.Push(constFrame(320, 0.3)); got != Endpoint { // 5 -> hits MaxFrames
		t.Fatalf("want Endpoint at MaxFrames, got %v", got)
	}
}

func TestEndpointerFixedThreshold(t *testing.T) {
	// FixedThreshold > 0 skips calibration: the first Push is already evaluated
	// against the fixed threshold.
	cfg := VADConfig{FrameSamples: 320, SilenceFrames: 2, MinSpeechFrames: 1, MaxFrames: 1000, CalibrationFrames: 0, FixedThreshold: 0.1}
	ep := NewEndpointer(cfg)
	mustContinue(t, ep.Push(constFrame(320, 0.3))) // speech immediately (no calibration)
	mustContinue(t, ep.Push(silenceFrame(320)))    // 1st trailing silence
	if got := ep.Push(silenceFrame(320)); got != Endpoint {
		t.Fatalf("want Endpoint with FixedThreshold, got %v", got)
	}
}

func mustContinue(t *testing.T, got Result) {
	t.Helper()
	if got != Continue {
		t.Fatalf("want Continue, got %v", got)
	}
}

func TestEndpointerSilenceDisabled(t *testing.T) {
	// SilenceFrames <= 0 disables silence endpointing: long trailing silence
	// must NOT endpoint; only MaxFrames (or external ctx cancel) ends it.
	cfg := VADConfig{FrameSamples: 320, SilenceFrames: 0, MinSpeechFrames: 1, MaxFrames: 50, CalibrationFrames: 0, ThresholdMultiplier: 3}
	ep := NewEndpointer(cfg)
	// speech then a long silence (longer than any normal SilenceFrames): never endpoints on silence
	for i := 0; i < 5; i++ {
		mustContinue(t, ep.Push(constFrame(320, 0.3)))
	}
	for i := 0; i < 40; i++ {
		mustContinue(t, ep.Push(silenceFrame(320)))
	}
	// only the MaxFrames cap (50 total pushes) ends it: we have pushed 45, push to 50
	var got Result
	for i := 0; i < 5; i++ {
		got = ep.Push(silenceFrame(320))
	}
	if got != Endpoint {
		t.Fatalf("want Endpoint at MaxFrames with silence disabled, got %v", got)
	}
}

