func TestServerClientRoundTrip(t *testing.T) {
	sock := filepath.Join(t.TempDir(), "test.sock")
	got := make(chan Command, 8)
	srv, err := NewServer(sock, func(c Command) string {
		got <- c
		return "ok:" + string(c)
	}, nil)
	if err != nil {
		t.Fatalf("NewServer: %v", err)
	}
	defer srv.Close()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	// NewServer has already bound the listener, so Dial queues in the kernel
	// backlog even before Accept runs; no sleep/synchronization is needed here.
	go srv.Serve(ctx)

	reply, err := Send(sock, CmdToggle)
	if err != nil {
		t.Fatalf("Send: %v", err)
	}
	if reply != "ok:toggle" {
		t.Fatalf("reply = %q, want ok:toggle", reply)
	}
	if c := <-got; c != CmdToggle {
		t.Fatalf("handler saw %q, want toggle", c)
	}
}

