	sock := filepath.Join(t.TempDir(), "test.sock")
	srv, err := NewServer(sock, func(Command) string { return "ok" }, nil)
	if err != nil {
		t.Fatalf("first NewServer: %v", err)
	}
	defer srv.Close()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go srv.Serve(ctx)

	if _, err := NewServer(sock, func(Command) string { return "ok" }, nil); err == nil {
		t.Fatal("second NewServer succeeded; want error (daemon already running)")
	}
}

