	}
}

func TestSubscribeStreamsLines(t *testing.T) {
	sock := filepath.Join(t.TempDir(), "s.sock")
	streamer := func(ctx context.Context, w io.Writer) {
		fmt.Fprintln(w, "idle")
		fmt.Fprintln(w, "listening")
		<-ctx.Done()
	}
	srv, err := NewServer(sock, func(Command) string { return "ok" }, streamer)
	if err != nil {
		t.Fatalf("NewServer: %v", err)
	}
	defer srv.Close()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go srv.Serve(ctx)

	got := make(chan string, 8)
	subCtx, subCancel := context.WithCancel(context.Background())
	defer subCancel()
	go Subscribe(subCtx, sock, func(s string) { got <- s })

	if s := <-got; s != "idle" {
		t.Fatalf("first state = %q, want idle", s)
	}
	if s := <-got; s != "listening" {
		t.Fatalf("second state = %q, want listening", s)
	}
}

func TestSubscribeUnsupportedWhenNilStreamer(t *testing.T) {
	sock := filepath.Join(t.TempDir(), "s.sock")
	srv, err := NewServer(sock, func(Command) string { return "ok" }, nil)
	if err != nil {
		t.Fatalf("NewServer: %v", err)
