}

func TestOneShotStillWorksAlongsideStreamer(t *testing.T) {
	sock := filepath.Join(t.TempDir(), "s.sock")
	srv, err := NewServer(sock, func(c Command) string { return "ok:" + string(c) }, func(ctx context.Context, w io.Writer) { <-ctx.Done() })
	if err != nil {
		t.Fatalf("NewServer: %v", err)
	}
	defer srv.Close()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go srv.Serve(ctx)

	if reply, _ := Send(sock, CmdStatus); reply != "ok:status" {
		t.Fatalf("one-shot reply = %q", reply)
