func TestSubscribeReturnsNilOnServerClose(t *testing.T) {
	sock := filepath.Join(t.TempDir(), "s.sock")
	// Streamer emits one line then RETURNS, which closes the connection.
	srv, err := NewServer(sock, func(Command) string { return "ok" }, func(ctx context.Context, w io.Writer) {
		fmt.Fprintln(w, "idle")
	})
	if err != nil {
		t.Fatalf("NewServer: %v", err)
	}
	defer srv.Close()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go srv.Serve(ctx)

	got := make(chan string, 4)
	err = Subscribe(context.Background(), sock, func(s string) { got <- s })
	if err != nil {
		t.Fatalf("Subscribe returned %v on clean server close, want nil", err)
	}
	if s := <-got; s != "idle" {
		t.Fatalf("state = %q, want idle", s)
	}
}

package daemon

import (
	"context"
	"errors"
	"io"
	"log"
	"testing"
	"time"

	"github.com/jimmykarily/voice-keyboard/pkg/audio"
	"github.com/jimmykarily/voice-keyboard/pkg/ipc"
	"github.com/jimmykarily/voice-keyboard/pkg/stt"
)

type fakeRecorder struct {
	started chan struct{}
	release chan recResult
}

type recResult struct {
	utt audio.Utterance
	err error
}

func (f *fakeRecorder) Record(ctx context.Context) (audio.Utterance, error) {
	select {
	case f.started <- struct{}{}:
	case <-ctx.Done():
		return audio.Utterance{}, nil
	}
	select {
	case r := <-f.release:
		return r.utt, r.err
	case <-ctx.Done():
		// manual stop: finalize a (nonempty) partial buffer
		return audio.Utterance{PCM: []float32{0.2}, SampleRate: 16000}, nil
	}
}

type fakeEngine struct {
	gotPCM chan []float32
	block  chan struct{} // if non-nil, Transcribe waits on it after signaling gotPCM
	text   string
	err    error
}

func (f *fakeEngine) Transcribe(pcm []float32, _ int) (string, error) {
	f.gotPCM <- pcm
	if f.block != nil {
		<-f.block
	}
	return f.text, f.err
}
func (f *fakeEngine) Close() error { return nil }

type fakeInjector struct{ typed chan string }

func (f *fakeInjector) Type(text string) error { f.typed <- text; return nil }

// --- streaming fakes ---

type fakeStreamRecorder struct{ ch chan []float32 }

func (f *fakeStreamRecorder) RecordStream(ctx context.Context) (<-chan []float32, error) {
	return f.ch, nil
}

type fakeStream struct {
	feeds  chan []float32
	deltas []string
	i      int
	tail   string
}

func (f *fakeStream) Feed(pcm []float32) (string, error) {
	f.feeds <- pcm
	d := ""
	if f.i < len(f.deltas) {
		d = f.deltas[f.i]
		f.i++
	}
	return d, nil
}
func (f *fakeStream) Finalize() (string, error) { return f.tail, nil }
func (f *fakeStream) Close() error              { return nil }

type fakeStreamEngine struct {
	stream   *fakeStream
	begins   chan string
	beginErr error // when non-nil, BeginStream returns this error instead of a stream
}

func (f *fakeStreamEngine) Transcribe(pcm []float32, _ int) (string, error) { return "", nil }
func (f *fakeStreamEngine) Close() error                                    { return nil }
func (f *fakeStreamEngine) BeginStream(lang string) (stt.Stream, error) {
	f.begins <- lang
	if f.beginErr != nil {
		return nil, f.beginErr
	}
	return f.stream, nil
}

func newTestDaemon(rec, pttRec audio.Recorder, eng stt.Engine, inj *fakeInjector, trailing bool) *Daemon {
	return New(rec, pttRec, nil, eng, inj, trailing, "auto", false, log.New(io.Discard, "", 0))
}

func newStreamingDaemon(recStream audio.StreamRecorder, eng stt.Engine, inj *fakeInjector, trailing bool) *Daemon {
	return New(nil, nil, recStream, eng, inj, trailing, "auto", true, log.New(io.Discard, "", 0))
}

func waitForStatus(t *testing.T, d *Daemon, want string) {
	t.Helper()
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		if d.Handle(ipc.CmdStatus) == want {
			return
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatalf("status never became %q (last seen %q)", want, d.Handle(ipc.CmdStatus))
}

func TestToggleCycleInjectsWithTrailingSpace(t *testing.T) {
	rec := &fakeRecorder{started: make(chan struct{}, 1), release: make(chan recResult, 1)}
	pttRec := &fakeRecorder{started: make(chan struct{}, 1), release: make(chan recResult, 1)}
	eng := &fakeEngine{gotPCM: make(chan []float32, 1), text: "Hello, world."}
	inj := &fakeInjector{typed: make(chan string, 1)}
	d := newTestDaemon(rec, pttRec, eng, inj, true)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go d.Run(ctx)

	if r := d.Handle(ipc.CmdToggle); r != "listening" {
		t.Fatalf("toggle reply = %q, want listening", r)
	}
	<-rec.started
	waitForStatus(t, d, "listening")

	rec.release <- recResult{utt: audio.Utterance{PCM: []float32{0.5}, SampleRate: 16000}}
	if pcm := <-eng.gotPCM; len(pcm) != 1 {
		t.Fatalf("engine got pcm len %d, want 1", len(pcm))
	}
	if got := <-inj.typed; got != "Hello, world. " {
		t.Fatalf("typed %q, want %q", got, "Hello, world. ")
	}
	waitForStatus(t, d, "idle")
}

func TestStopFinalizesPartial(t *testing.T) {
	rec := &fakeRecorder{started: make(chan struct{}, 1), release: make(chan recResult, 1)}
	pttRec := &fakeRecorder{started: make(chan struct{}, 1), release: make(chan recResult, 1)}
	eng := &fakeEngine{gotPCM: make(chan []float32, 1), text: "partial."}
	inj := &fakeInjector{typed: make(chan string, 1)}
	d := newTestDaemon(rec, pttRec, eng, inj, false)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go d.Run(ctx)

	d.Handle(ipc.CmdToggle)
	<-rec.started
	if r := d.Handle(ipc.CmdStop); r != "stopping" {
		t.Fatalf("stop reply = %q, want stopping", r)
	}
	<-eng.gotPCM
	if got := <-inj.typed; got != "partial." {
		t.Fatalf("typed %q, want partial. (no trailing space)", got)
	}
	waitForStatus(t, d, "idle")
}

func TestToggleWhileTranscribingIsBusy(t *testing.T) {
	rec := &fakeRecorder{started: make(chan struct{}, 1), release: make(chan recResult, 1)}
	pttRec := &fakeRecorder{started: make(chan struct{}, 1), release: make(chan recResult, 1)}
	eng := &fakeEngine{gotPCM: make(chan []float32, 1), block: make(chan struct{}), text: "x."}
	inj := &fakeInjector{typed: make(chan string, 1)}
	d := newTestDaemon(rec, pttRec, eng, inj, false)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go d.Run(ctx)

	d.Handle(ipc.CmdToggle)
	<-rec.started
	rec.release <- recResult{utt: audio.Utterance{PCM: []float32{0.5}, SampleRate: 16000}}
	<-eng.gotPCM // transcription has started and is blocked
	waitForStatus(t, d, "transcribing")

	if r := d.Handle(ipc.CmdToggle); r != "busy" {
		t.Fatalf("toggle-while-transcribing reply = %q, want busy", r)
	}
	close(eng.block) // let transcription finish
	<-inj.typed
	waitForStatus(t, d, "idle")
}

func TestQuitStopsRun(t *testing.T) {
	rec := &fakeRecorder{started: make(chan struct{}, 1), release: make(chan recResult, 1)}
	pttRec := &fakeRecorder{started: make(chan struct{}, 1), release: make(chan recResult, 1)}
	eng := &fakeEngine{gotPCM: make(chan []float32, 1), text: "x."}
