		t.Fatal("Run did not return after quit")
	}
}

func TestCancelWhileTranscribingWaitsForEngine(t *testing.T) {
	rec := &fakeRecorder{started: make(chan struct{}, 1), release: make(chan recResult, 1)}
	pttRec := &fakeRecorder{started: make(chan struct{}, 1), release: make(chan recResult, 1)}
	eng := &fakeEngine{gotPCM: make(chan []float32, 1), block: make(chan struct{}), text: "x."}
	inj := &fakeInjector{typed: make(chan string, 1)}
	d := newTestDaemon(rec, pttRec, eng, inj, false)

	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan error, 1)
	go func() { done <- d.Run(ctx) }()

	d.Handle(ipc.CmdToggle)
	<-rec.started
	rec.release <- recResult{utt: audio.Utterance{PCM: []float32{0.5}, SampleRate: 16000}}
	<-eng.gotPCM // transcription started, now blocked on eng.block
	waitForStatus(t, d, "transcribing")

	// Cancel while the (uncancellable) cgo-style transcription is in flight. Run
	// MUST NOT return until the engine call completes; otherwise the caller would
	// Close() the engine underneath a running Transcribe.
	cancel()
	select {
	case <-done:
		t.Fatal("Run returned while transcription still in flight")
	case <-time.After(100 * time.Millisecond):
		// expected: Run is blocked in wg.Wait until the engine finishes
	}

	close(eng.block) // let Transcribe finish
	select {
	case err := <-done:
		if !errors.Is(err, context.Canceled) {
			t.Fatalf("Run returned %v, want context.Canceled", err)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("Run did not return after engine finished")
	}
}

