		t.Fatalf("start reply = %q, want listening", r)
	}
	// start must drive the PTT recorder, not the VAD recorder
	select {
	case <-pttRec.started:
	case <-time.After(2 * time.Second):
		t.Fatal("start did not use the push-to-talk recorder")
	}
	select {
	case <-rec.started:
		t.Fatal("start wrongly used the VAD recorder")
	case <-time.After(50 * time.Millisecond):
	}

	// stop finalizes the PTT recording (its ctx is cancelled -> returns partial)
	if r := d.Handle(ipc.CmdStop); r != "stopping" {
		t.Fatalf("stop reply = %q, want stopping", r)
	}
	<-eng.gotPCM
	<-inj.typed
	waitForStatus(t, d, "idle")
