	defer cancel()
	go d.Run(ctx)

	subCtx, subCancel := context.WithCancel(context.Background())
	ch := d.Subscribe(subCtx)
	<-ch // idle
	subCancel()

	deadline := time.After(2 * time.Second)
	for {
		select {
		case _, ok := <-ch:
			if !ok {
				return // channel closed: unsubscribed cleanly
			}
		case <-deadline:
			t.Fatal("subscribe channel not closed after ctx cancel")
		}
	}
