func TestStreamingTypesDeltasThenTail(t *testing.T) {
	ch := make(chan []float32)
	recStream := &fakeStreamRecorder{ch: ch}
	stream := &fakeStream{feeds: make(chan []float32, 8), deltas: []string{"hello ", "world"}, tail: "!"}
	eng := &fakeStreamEngine{stream: stream, begins: make(chan string, 1)}
	inj := &fakeInjector{typed: make(chan string, 8)}
	d := newStreamingDaemon(recStream, eng, inj, false)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go d.Run(ctx)

	if r := d.Handle(ipc.CmdStart); r != "listening" {
		t.Fatalf("start reply = %q, want listening", r)
	}
	if lang := <-eng.begins; lang != "auto" {
		t.Fatalf("BeginStream lang = %q, want auto", lang)
	}
	waitForStatus(t, d, "listening")

	// Two chunks -> two deltas injected in order.
	ch <- []float32{0.1}
	<-stream.feeds
	if got := <-inj.typed; got != "hello " {
		t.Fatalf("first delta = %q, want %q", got, "hello ")
	}
	ch <- []float32{0.2}
	<-stream.feeds
	if got := <-inj.typed; got != "world" {
		t.Fatalf("second delta = %q, want %q", got, "world")
	}

	// Key release: cancel -> recorder closes the channel -> finalize tail typed.
	d.Handle(ipc.CmdStop)
	close(ch) // simulate the recorder draining and closing after cancel
	if got := <-inj.typed; got != "!" {
		t.Fatalf("finalize tail = %q, want %q", got, "!")
	}
	waitForStatus(t, d, "idle")
}

func TestStreamingDrainsAllChunksBeforeFinalize(t *testing.T) {
	ch := make(chan []float32, 3)
	recStream := &fakeStreamRecorder{ch: ch}
