	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go d.Run(ctx)

	d.Handle(ipc.CmdStart)
	<-eng.begins

	ch <- []float32{1}
	ch <- []float32{2}
	ch <- []float32{3}
	close(ch) // all queued audio must be fed before finalize

	for i := 0; i < 3; i++ {
		<-stream.feeds
	}
	if got := <-inj.typed; got != "done" {
		t.Fatalf("tail = %q, want %q (finalize must run only after all chunks fed)", got, "done")
	}
	waitForStatus(t, d, "idle")
}

// closeTrackingEngine records whether Close was called, so a reload can be
// observed to release the previous engine.
