	inj := &fakeInjector{typed: make(chan string, 8)}
	d := newStreamingDaemon(recStream, eng, inj, false)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go d.Run(ctx)

	if r := d.Handle(ipc.CmdStart); r != "error" {
		t.Fatalf("start reply = %q, want error", r)
	}
	if lang := <-eng.begins; lang != "auto" {
		t.Fatalf("BeginStream lang = %q, want auto", lang)
	}

	// The reply arrives only after startStreaming returns, and the state
	// machine never sets StateListening before BeginStream succeeds, so the
	// status is already idle with no race.
	if got := d.Handle(ipc.CmdStatus); got != "idle" {
		t.Fatalf("status after failed BeginStream = %q, want idle", got)
	}
	waitForStatus(t, d, "idle") // guards against any later async transition too

	select {
	case got := <-inj.typed:
		t.Fatalf("unexpected injection %q after BeginStream failure", got)
	default:
	}
	select {
	case chunk := <-stream.feeds:
		t.Fatalf("unexpected Feed(%v) after BeginStream failure", chunk)
	default:
	}
}

