type fakeStore struct {
	cur     Settings
	saved   *Settings
	saveErr error
}

func (f *fakeStore) Load() (Settings, error) { return f.cur, nil }
func (f *fakeStore) Save(s Settings) error {
	if f.saveErr != nil {
		return f.saveErr
	}
	f.saved = &s
	return nil
}

type fakeReloader struct {
	applied *Settings
	err     error
}

func (f *fakeReloader) Apply(s Settings) error {
	if f.err != nil {
		return f.err
	}
	f.applied = &s
	return nil
}

func newTestServer(t *testing.T, store ConfigStore, rel Reloader) *Server {
	t.Helper()
	srv, err := New(Deps{Store: store, Reloader: rel, Downloader: NewDownloader(nil), ModelDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	return srv
}

// do builds a request with the given token and Host and runs it through Handler.
func do(srv *Server, method, path, token, host, body string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(method, path, strings.NewReader(body))
	if token != "" {
		req.Header.Set("X-Settings-Token", token)
	}
	if host != "" {
		req.Host = host
	}
	rec := httptest.NewRecorder()
	srv.Handler().ServeHTTP(rec, req)
	return rec
}

