func TestDefaultMatchesAudioDefaults(t *testing.T) {
	c := Default()
	a := audio.DefaultConfig()
	if c.Audio.SilenceSec != a.SilenceSeconds {
		t.Errorf("SilenceSec = %v, want %v", c.Audio.SilenceSec, a.SilenceSeconds)
	}
	if c.Audio.MinSpeechSec != a.MinSpeechSeconds {
		t.Errorf("MinSpeechSec = %v, want %v", c.Audio.MinSpeechSec, a.MinSpeechSeconds)
	}
	if c.Audio.MaxUtteranceSec != a.MaxUtteranceSeconds {
		t.Errorf("MaxUtteranceSec = %v, want %v", c.Audio.MaxUtteranceSec, a.MaxUtteranceSeconds)
	}
	if c.Audio.CalibrationSec != a.CalibrationSeconds {
		t.Errorf("CalibrationSec = %v, want %v", c.Audio.CalibrationSec, a.CalibrationSeconds)
	}
	if float32(c.Audio.Threshold) != a.FixedThreshold {
		t.Errorf("Threshold = %v, want %v", c.Audio.Threshold, a.FixedThreshold)
	}
	if float32(c.Audio.MaxThreshold) != a.MaxThreshold {
		t.Errorf("MaxThreshold = %v, want %v", c.Audio.MaxThreshold, a.MaxThreshold)
	}
	if c.Inject.Backend != "wtype" {
		t.Errorf("Backend = %q, want wtype", c.Inject.Backend)
	}
	if !c.Inject.TrailingSpace {
		t.Error("TrailingSpace = false, want true")
	}
	if c.Engine.ModelPath == "" {
		t.Error("ModelPath is empty")
	}
}

func TestAudioConfigMapping(t *testing.T) {
	c := Default()
	c.Audio.SilenceSec = 1.5
	c.Audio.MinSpeechSec = 0.2
	c.Audio.MaxUtteranceSec = 30
	c.Audio.CalibrationSec = 0.4
	c.Audio.Threshold = 0.02
	c.Audio.MaxThreshold = 0.09

	a := c.AudioConfig()
	if a.SilenceSeconds != 1.5 || a.MinSpeechSeconds != 0.2 || a.MaxUtteranceSeconds != 30 || a.CalibrationSeconds != 0.4 {
		t.Errorf("seconds not mapped: %+v", a)
	}
	if a.FixedThreshold != float32(0.02) {
		t.Errorf("FixedThreshold = %v, want 0.02", a.FixedThreshold)
	}
	if a.MaxThreshold != float32(0.09) {
		t.Errorf("MaxThreshold = %v, want 0.09", a.MaxThreshold)
	}
	def := audio.DefaultConfig()
	if a.SampleRate != def.SampleRate || a.FrameMillis != def.FrameMillis || a.ThresholdMultiplier != def.ThresholdMultiplier {
		t.Errorf("unexposed fields drifted from audio defaults: %+v", a)
	}
	if a.PushToTalk {
		t.Error("AudioConfig should not set PushToTalk")
	}
}

