func TestWriteDefaultRoundTrips(t *testing.T) {
	p := filepath.Join(t.TempDir(), "config.toml")
	if err := WriteDefault(p); err != nil {
		t.Fatalf("WriteDefault: %v", err)
	}
	c, err := Load(p)
	if err != nil {
		t.Fatalf("Load written file: %v", err)
	}
	want := Default()
	// Compare the effective configuration. The raw Audio float64 fields can
	// differ by a float32-widening artifact (float64(float32(0.05)) != 0.05),
	// but the values that actually drive the daemon (the audio.Config, the model
	// path, and the inject options) must match exactly.
	if c.AudioConfig() != want.AudioConfig() {
		t.Errorf("AudioConfig mismatch:\n got: %+v\nwant: %+v", c.AudioConfig(), want.AudioConfig())
	}
	if c.Engine != want.Engine {
		t.Errorf("Engine mismatch:\n got: %+v\nwant: %+v", c.Engine, want.Engine)
	}
	if c.Inject != want.Inject {
		t.Errorf("Inject mismatch:\n got: %+v\nwant: %+v", c.Inject, want.Inject)
	}
}

