package main

import (
	"path/filepath"
	"sync"
	"testing"

	"github.com/jimmykarily/voice-keyboard/pkg/config"
	"github.com/jimmykarily/voice-keyboard/pkg/daemon"
	"github.com/jimmykarily/voice-keyboard/pkg/stt"
	"github.com/jimmykarily/voice-keyboard/pkg/websettings"
)

// TestConfigBridge_ConcurrentSaveAndSnapshot exercises configBridge under
// concurrent access: half the goroutines call Save (write path), half take a
// locked snapshot via current() and fold it through the pure toConfig (read
// path). Before the fix, toConfig read b.cur without holding b.mu, so this
// test raced under `go test -race`. It must stay race-clean.
func TestConfigBridge_ConcurrentSaveAndSnapshot(t *testing.T) {
	dir := t.TempDir()
	b := &configBridge{
		path:     filepath.Join(dir, "config.toml"),
		modelDir: dir,
		cur:      config.Default(),
	}

	settings := websettings.Settings{
		ModelPath:      "some-model.gguf",
		TargetLang:     "auto",
		Streaming:      true,
		TrailingSpace:  true,
		Backend:        "wtype",
		SilenceSec:     0.7,
		MinSpeechSec:   0.1,
		MaxUtterSec:    20.0,
		CalibrationSec: 0.3,
		Threshold:      0.0,
		MaxThreshold:   0.05,
	}

	const n = 50
	var wg sync.WaitGroup
	wg.Add(2 * n)

	for i := 0; i < n; i++ {
		go func() {
			defer wg.Done()
			if err := b.Save(settings); err != nil {
				t.Errorf("Save: %v", err)
			}
		}()
		go func() {
			defer wg.Done()
			cur := b.current()
			_ = b.toConfig(cur, settings)
		}()
	}

	wg.Wait()
}

// stubEngine is a minimal stt.Engine returned by fake engine factories in
// these tests. The fake applier below never calls Transcribe, so it only
// needs to satisfy the interface.
type stubEngine struct{}

func (stubEngine) Transcribe(pcm []float32, sampleRate int) (string, error) { return "", nil }
func (stubEngine) Close() error                                             { return nil }

// fakeApplier is a configApplier that records the last ReloadRequest it
// received instead of driving a real daemon.
type fakeApplier struct {
	mu      sync.Mutex
	lastReq daemon.ReloadRequest
	calls   int
}

func (f *fakeApplier) ApplyConfig(req daemon.ReloadRequest) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.lastReq = req
	f.calls++
	return nil
}

func (f *fakeApplier) last() daemon.ReloadRequest {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.lastReq
}

func (f *fakeApplier) count() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.calls
}

// engineFactorySpy wraps a fake engine factory and records the model paths it
// was called with.
type engineFactorySpy struct {
	mu    sync.Mutex
	calls []string
}

func (s *engineFactorySpy) factory(modelPath string) (stt.Engine, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.calls = append(s.calls, modelPath)
	return stubEngine{}, nil
}

func (s *engineFactorySpy) callCount() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.calls)
}

// TestReloadBridge_SwitchingModel_RebuildsEngine guards the CRITICAL bug where
// switching models in the GUI never rebuilt the engine. The bug arose when the
// save flow ran Store.Save before Reloader.Apply: Save mutated the store's
// in-memory config to the new settings first, so a reloadBridge that compared
// the requested model against the store's (now-new) config always found them
// equal and never rebuilt the engine. This test deliberately drives Save THEN
// Apply (the original order) so it still fails against that buggy comparison,
// and passes because Apply compares against appliedModelPath, independent of
// store state or call order.
func TestReloadBridge_SwitchingModel_RebuildsEngine(t *testing.T) {
	dir := t.TempDir()
	cfg := config.Default()
	cfg.Engine.ModelPath = filepath.Join(dir, "old.gguf")

	store := &configBridge{path: filepath.Join(dir, "config.toml"), modelDir: dir, cur: cfg}
	applier := &fakeApplier{}
	spy := &engineFactorySpy{}
	reloader := &reloadBridge{
		applier:          applier,
		store:            store,
		newEngine:        spy.factory,
		appliedModelPath: cfg.Engine.ModelPath,
	}

	settings, err := store.Load()
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	settings.ModelPath = "new.gguf" // a different model, as a bare filename (as the UI sends)

	// Deliberately Save THEN Apply (the original order that triggered the bug):
	// the comparison against appliedModelPath must detect the change anyway.
	if err := store.Save(settings); err != nil {
		t.Fatalf("Save: %v", err)
	}
	if err := reloader.Apply(settings); err != nil {
		t.Fatalf("Apply: %v", err)
	}

	wantPath := filepath.Join(dir, "new.gguf")
	if applier.last().Engine == nil {
		t.Fatal("ReloadRequest.Engine is nil; switching models must rebuild the engine")
	}
	if got := spy.callCount(); got != 1 {
		t.Fatalf("engine factory calls = %d, want 1", got)
	}
	if got := spy.calls[0]; got != wantPath {
		t.Fatalf("engine factory called with %q, want %q", got, wantPath)
	}
	reloader.mu.Lock()
	got := reloader.appliedModelPath
	reloader.mu.Unlock()
	if got != wantPath {
		t.Fatalf("appliedModelPath = %q, want %q", got, wantPath)
	}
}

// TestReloadBridge_InvalidConfig_NotApplied verifies Apply rejects an invalid
// config (via config.Validate) before building an engine or calling the daemon,
// so a bad settings payload never mutates daemon state.
func TestReloadBridge_InvalidConfig_NotApplied(t *testing.T) {
	dir := t.TempDir()
	cfg := config.Default()
	cfg.Engine.ModelPath = filepath.Join(dir, "old.gguf")

	store := &configBridge{path: filepath.Join(dir, "config.toml"), modelDir: dir, cur: cfg}
	applier := &fakeApplier{}
	spy := &engineFactorySpy{}
	reloader := &reloadBridge{
		applier:          applier,
		store:            store,
		newEngine:        spy.factory,
		appliedModelPath: cfg.Engine.ModelPath,
	}

	settings, err := store.Load()
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	settings.SilenceSec = 0 // invalid: silence_sec must be > 0

	if err := reloader.Apply(settings); err == nil {
		t.Fatal("Apply must reject an invalid config")
	}
	if got := spy.callCount(); got != 0 {
		t.Fatalf("engine factory called %d times on invalid config, want 0", got)
	}
	if got := applier.count(); got != 0 {
		t.Fatalf("ApplyConfig called %d times on invalid config, want 0", got)
	}
}

// TestReloadBridge_SameModel_DoesNotRebuildEngine is the mirror case: saving
// settings that keep the same model must NOT rebuild the engine.
func TestReloadBridge_SameModel_DoesNotRebuildEngine(t *testing.T) {
	dir := t.TempDir()
	cfg := config.Default()
	cfg.Engine.ModelPath = filepath.Join(dir, "old.gguf")

	store := &configBridge{path: filepath.Join(dir, "config.toml"), modelDir: dir, cur: cfg}
	applier := &fakeApplier{}
	spy := &engineFactorySpy{}
	reloader := &reloadBridge{
		applier:          applier,
		store:            store,
		newEngine:        spy.factory,
		appliedModelPath: cfg.Engine.ModelPath,
	}

	settings, err := store.Load()
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	settings.ModelPath = "old.gguf" // same model, unchanged

	if err := store.Save(settings); err != nil {
		t.Fatalf("Save: %v", err)
	}
	if err := reloader.Apply(settings); err != nil {
		t.Fatalf("Apply: %v", err)
	}

	if applier.last().Engine != nil {
		t.Fatal("ReloadRequest.Engine is non-nil; saving the same model must not rebuild the engine")
	}
	if got := spy.callCount(); got != 0 {
		t.Fatalf("engine factory calls = %d, want 0", got)
	}
}
